class Solution:
    def maximumAND(self, nums: List[int], k: int, m: int) -> int:
        def cost(x: int, M: int) -> int:
            if x & M == M:
                return 0
            best = M - x if M >= x else float('inf')
            for b in range(31):
                if not (M >> b) & 1:
                    v = ((M >> b) << b) | (1 << b) | (M & ((1 << b) - 1))
                    if v >= x:
                        best = min(best, v - x)
            return best

        ans = 0
        for b in range(30, -1, -1):
            cand = ans | (1 << b)
            costs = sorted(cost(x, cand) for x in nums)
            total = sum(costs[:m])
            if total <= k:
                ans = cand
                k -= total
        return ans

