class Solution {
    private long cost(long x, long M) {
        if ((x & M) == M) return 0;
        long best = Long.MAX_VALUE;
        if (M >= x) best = M - x;
        for (int b = 0; b < 31; b++) {
            if (((M >> b) & 1) == 0) {
                long v = ((M >> b) << b) | (1L << b) | (M & ((1L << b) - 1));
                if (v >= x) best = Math.min(best, v - x);
            }
        }
        return best;
    }

    public long maximumAND(int[] nums, long k, int m) {
        long ans = 0;
        Long[] costs = new Long[nums.length];
        for (int b = 30; b >= 0; b--) {
            long cand = ans | (1L << b);
            for (int i = 0; i < nums.length; i++)
                costs[i] = cost(nums[i], cand);
            Arrays.sort(costs);
            long total = 0;
            for (int i = 0; i < m; i++) total += costs[i];
            if (total <= k) {
                ans = cand;
                k -= total;
            }
        }
        return ans;
    }
}

