var maximumAND = function(nums, k, m) {
    const cost = (x, M) => {
        if ((x & M) === M) return 0;
        let best = Infinity;
        if (M >= x) best = M - x;
        for (let b = 0; b < 31; b++) {
            if (!((M >> b) & 1)) {
                const v = ((M >> b) << b) | (1 << b) | (M & ((1 << b) - 1));
                if (v >= x) best = Math.min(best, v - x);
            }
        }
        return best;
    };
    let ans = 0;
    for (let b = 30; b >= 0; b--) {
        const cand = ans | (1 << b);
        const costs = nums.map(x => cost(x, cand)).sort((a, b) => a - b);
        let total = 0;
        for (let i = 0; i < m; i++) total += costs[i];
        if (total <= k) {
            ans = cand;
            k -= total;
        }
    }
    return ans;
};
